const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const n = parseInt(input[0], 10);
    const instructions = input[1];

    let current = 1;

    for (let i = 0; i < n; i++) {
        if (instructions[i] === 'E') {
            current = 2 * current;
        } else if (instructions[i] === 'D') {
            current = 2 * current + 1;
        }
    }

    console.log(current);
}

main();
